function batchGroups(){return [...new Set(batchFiles.map(entry=>entry.group))];}
function addBatchFiles(files){
 if(batchLocked)fail('Cierra el lote finalizado antes de elegir más archivos.',409);
 const selected=files.map(file=>{const path=file.webkitRelativePath||file.name,parts=path.split('/');if(path.length>200||parts.some(p=>!p||p==='.'||p==='..')||path.includes('\\'))fail('Revisa la ruta: usa nombres de carpeta más cortos, hasta 200 caracteres en total.',422);return {file,path,group:parts.length>2?parts.slice(0,2).join('/'):parts.length===2?parts[0]:'Archivos seleccionados'};});
 const paths=new Set(batchFiles.map(entry=>entry.path));for(const entry of selected){if(paths.has(entry.path))fail('La ruta ya está seleccionada: '+entry.path+'. No se agregó esta selección. Usa carpetas con nombres distintos para distinguir los orígenes.',422);paths.add(entry.path);}
 if(batchFiles.length+selected.length>250)fail('El máximo es 250 archivos por carga. Divide las carpetas en grupos más pequeños.',422);
 batchFiles.push(...selected);renderBatchSelection();
}
function renderBatchSelection(){
 batchPlan=null;$('batch-warning').replaceChildren();
 const form=$('edit-form'),groups=batchGroups(),vehicleMode=form.elements.subject_kind.value==='vehicle',single=form.elements.vehicle_id;
 single.disabled=!vehicleMode||groups.length>1;single.required=vehicleMode&&groups.length<=1;if(!vehicleMode)single.value='0';form.elements.confirm_destination.checked=false;
 const assignments=vehicleMode&&groups.length>1?`<p class="help">Asigna explícitamente un vehículo a cada carpeta. No se deducen patentes ni se fusionan vehículos por el nombre de carpeta.</p>${groups.map((group,i)=>`<label>${esc(group)}<select name="folder_vehicle_${i}" data-batch-group="${i}"><option value="0">Seleccionar vehículo para esta carpeta</option>${data.fileSubjects.vehicles.map(v=>`<option value="${v.id}" ${batchVehicleMap.get(group)===v.id?'selected':''}>${esc((v.plate||'Sin patente')+' · '+v.label)}</option>`).join('')}</select></label>`).join('')}`:'';
 $('batch-preview').innerHTML=`<p class="help">${batchFiles.length} archivos · ${groups.length} grupos de origen · ${(batchFiles.reduce((n,e)=>n+e.file.size,0)/1048576).toFixed(1)} MiB</p>${assignments}<ul class="batch-list">${batchFiles.map((entry,i)=>`<li>${esc(entry.path)} <button type="button" class="secondary" data-batch-remove="${i}" aria-label="Quitar ${esc(entry.path)}">Quitar</button></li>`).join('')}</ul>`;
}
async function saveBatchFiles(p){
 const form=$('edit-form'),entries=[...batchFiles],groups=batchGroups();
 if(batchLocked)fail('Este lote ya se procesó. Cierra y revisa la lista antes de continuar.',409);
 if(!entries.length||entries.length>250)fail('Selecciona entre 1 y 250 archivos o añade carpetas.',422);
 const vehicleFor=entry=>groups.length>1?batchVehicleMap.get(entry.group):p.vehicle_id;
 if(p.subject_kind==='vehicle')for(const entry of entries)if(!data.fileSubjects.vehicles.some(v=>v.id===vehicleFor(entry)))fail('Selecciona un vehículo válido para cada carpeta: '+entry.group,422);
 if(!form.elements.confirm_destination.checked)fail('Confirma el destino de los archivos.',422);
 let total=0;
 for(const {file} of entries){fileMediaType(file);if(!file.size||file.size>15*1048576)fail('Cada archivo debe tener contenido y no superar 15 MiB: '+file.name,422);if(file.name.length>160)fail('Acorta el nombre a 160 caracteres: '+file.name,422);total+=file.size;}
 if(total>250*1048576)fail('La carga excede 250 MiB. Divídela en grupos más pequeños.',422);
 if(!batchPlan){
  $('save').textContent='Comprobando archivos existentes…';
  const requested=[];for(const entry of entries)requested.push({path:entry.path,subject_kind:p.subject_kind,vehicle_id:p.subject_kind==='vehicle'?vehicleFor(entry):null,sha256:await hashFile(entry.file)});
  const response=await request('/ops/files/batch/preview','POST',{entries:requested});
  if(response.items.length!==entries.length)fail('La comprobación no devolvió todos los destinos.',409);
  batchPlan={items:response.items,needsConfirmation:response.items.some(item=>item.status==='replace')};
  if(batchPlan.needsConfirmation){
   const replacements=response.items.filter(item=>item.status==='replace');
   $('batch-warning').innerHTML=`<div class="banner"><b>Advertencia: ${replacements.length} documentos se actualizarán en su destino.</b><ul class="batch-list">${replacements.map(item=>`<li>${esc(item.subject_name)} · ${esc(item.path)} · versión actual ${item.expected_version}</li>`).join('')}</ul><p>La nueva versión pasará a ser la actual. Las anteriores permanecerán en el historial y la nueva requerirá revisión. Los archivos idénticos se omitirán.</p><label><span><input type="checkbox" name="confirm_replacements"> Confirmo los reemplazos indicados en sus destinos.</span></label></div>`;
   return {awaitingReplacement:true};
  }
 }
 if(batchPlan.needsConfirmation&&!form.elements.confirm_replacements?.checked)fail('Confirma la advertencia de reemplazo antes de actualizar los documentos.',422);
 batchLocked=true;for(const field of form.querySelectorAll('input,select,button'))field.disabled=true;
 let saved=0,skipped=0;
 for(let index=0;index<entries.length;index++){
  const entry=entries[index],{file,path}=entry,plan=batchPlan.items[index];
  if(plan.status==='identical'){skipped++;continue;}
  try{
   $('batch-preview').textContent=`Guardados ${saved}, idénticos omitidos ${skipped}, de ${entries.length}. Analizando: ${path}. Mantén esta ventana abierta.`;
   const query=new URLSearchParams({path,subject_kind:p.subject_kind,expected_version:String(plan.expected_version),allow_replace:String(batchPlan.needsConfirmation)});
   if(plan.document_id)query.set('expected_document_id',plan.document_id);if(p.subject_kind==='vehicle')query.set('vehicle_id',vehicleFor(entry));
   const response=await binaryRequest('/ops/files/batch/item?'+query,'POST',file),result=await response.json();if(result.status==='identical')skipped++;else saved++;
  }catch(error){
   $('batch-preview').textContent=`Guardados: ${saved}; idénticos omitidos: ${skipped}. Lote detenido en ${path}. Archivos posteriores sin intentar: ${entries.length-index-1}.`;
   throw Error(error.message+' Actualiza y comprueba el documento afectado antes de reintentar. Los archivos anteriores se conservaron. No vuelvas a cargar el lote completo sin comprobar los destinos.');
  }
 }
 return {saved,skipped};
}
async function hashFile(file){
 const bytes=typeof file.arrayBuffer==='function'?await file.arrayBuffer():await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('No se pudo leer '+file.name));reader.readAsArrayBuffer(file);});
 if(!crypto.subtle)fail('La comprobación de duplicados requiere acceder por HTTPS.',422);
 return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');
}

