 if(actionName==='assignment-history'||actionName==='review-history'){const rows=await request(actionName==='assignment-history'?`/ops/assignments/${n}/history`:`/ops/documents/${n}/reviews`);await openDetail('Historial de cambios',rows.map(r=>`<div class="row"><div><b>${esc(r.reason||states[r.state]||r.state||'Cambio de asignación')}</b><small>${esc(r.at)} · Usuario ${esc(r.user_id)}</small>${r.after?'<small>'+esc(r.after.work_date)+' · '+esc(states[r.after.state])+'</small>':''}</div></div>`).join('')||'<p class="help">Aún no hay cambios registrados.</p>');return;}
 if(actionName==='report'){const r=await request(`/ops/services/${n}/closeout`),s=data.services.find(s=>s.id===n);data.closeout=r;await openDetail('Cierre · '+s.code,`${pill(r.ready_to_close?'approved':'observed',r.ready_to_close?'Condiciones completas':'Cierre pendiente')}<ul class="checklist"><li>${r.open_tasks} tareas sin resolver</li><li>${r.pending_attendance} asistencias por registrar</li><li>${r.other_blocking_requirements.length} requisitos adicionales pendientes</li>${r.workers.map(w=>`<li>${esc(workerName(w.worker_id))}: ${w.ready?'Requisitos completos':w.configured?w.blocking_count+' requisitos pendientes':'Requisitos sin configurar'}</li>`).join('')||'<li>Sin personal asignado.</li>'}</ul><p class="help">La fecha del servicio debe haber finalizado y la evidencia debe estar revisada, vigente y respaldada por archivo.</p><div class="actions">${action('export-closeout','Exportar checklist',n)}${can('users.manage')&&r.ready_to_close&&s.status!=='completed'?action('close-service','Cerrar servicio',n):''}</div>`);return;}
 if(actionName==='export-closeout'){const r=data.closeout;exportFile('PAGDOC_cierre_demo_'+n+'.csv',[['Servicio','Persona','Requisitos configurados','Completo','Bloqueos'],...r.workers.map(w=>[serviceName(n),workerName(w.worker_id),w.configured,w.ready,w.blocking_count])]);return;}
 if(actionName==='close-service'){const s=data.services.find(s=>s.id===n);await request(`/ops/services/${n}/close`,'POST',{expected_version:s.version});$('editor').close();await load();note('Servicio cerrado y acción registrada.');return;}
 if(actionName==='export-plan'){exportFile('PAGDOC_planificacion_'+iso(month).slice(0,7)+'.csv',[['Fecha','Persona','Servicio','Programado','Realizado'],...data.assignments.map(a=>[a.work_date,workerName(a.worker_id),serviceName(a.service_id),states[a.state],states[a.actual]])]);note('Mes exportado con el filtro seleccionado.');return;}
 if(actionName==='new-requirement'){openForm('requirement',null,'Crear requisito documental',input('name','Nombre del requisito','text','','required minlength="2" maxlength="160"')+input('warning_days','Avisar con días de anticipación','number','30','min="0" max="3650" required'),'Esta pantalla configura requisitos de trabajadores; cada proyecto debe asociarlos de forma explícita.');return;}
